// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(address nonOwner, uint256 amount) public {
        vm.assume(nonOwner != address(c));
        vm.deal(nonOwner, amount);
        vm.prank(nonOwner);
        (bool ok, ) = address(c).call{value: amount}(abi.encodeWithSignature("sendMoney(address,uint256,bytes)", address(0), 0, ""));
        assertTrue(!ok);
    }
}
